</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

typedef long double dbl;

static dbl A[1 << 20];
static dbl B[1 << 20];
static int n, k;
static double p[25];

double Solve(int vr) {
    const double EPS = 1E-9;
    if (p[vr] < EPS) return 0.0;

    A[0] = 1.0L;
    B[0] = 0.0L;

    int total = 1 << n;

    for (int msk = 1; msk < total; ++msk) {
        if (msk & (1 << vr)) continue;

        dbl a = 0.0L, b = 0.0L, same = 0.0L;

        for (int i = 0; i < n; ++i) {
            if (i != vr && (msk & (1 << i))) {
                same += p[i];
                a += A[msk ^ (1 << i)] * p[i];
                b += B[msk ^ (1 << i)] * p[i];
            }
        }

        A[msk] = a / (1.0L - same);
        B[msk] = b / (1.0L - same);
    }

    dbl ta = 1.0L, tb = 0.0L;
    for (int msk = 1; msk < total; ++msk) {
        if (!(msk & (1 << vr))) {
            ta += A[msk];
            tb += B[msk];
        }
    }

    dbl alp = (1.0L - tb) / ta;

    dbl ba = 0.0L, bb = 0.0L;
    for (int msk = 0; msk < total; ++msk) {
        if (!(msk & (1 << vr)) && __builtin_popcount(msk) >= k) {
            ba += A[msk];
            bb += B[msk];
        }
    }

    return (double)(1.0L - (alp * ba + bb));
}

int main() {
    scanf("%d%d", &n, &k);
    for (int i = 0; i < n; ++i) scanf("%lf", &p[i]);

    for (int i = 0; i < n; ++i) {
        if (i) putchar(' ');
        printf("%.12f", Solve(i));
    }
    putchar('\n');

    return 0;
}
